INSERT INTO site_news (title, body, published) VALUES
('Подписки «Бронза», «Серебро» и «Золото» и новый форум',
E'На сайте появились три уровня подписки: «Бронза» — 99 ₽, «Серебро» — 199 ₽ и «Золото» — 299 ₽ за 30 дней.\n\n«Бронза»: доступ ко всем чатам и Премиум-чату.\n«Серебро»: всё из «Бронзы» и доступ к форуму.\n«Золото»: всё из «Серебра» и рассылка сводок и дайджестов AiTraderKa на вашу почту, а также закрытый раздел «Золотой клуб».\n\nФорум находится в текстовых каналах между «уведомлениями» и «статьями». Разделы, подразделы и права доступа настраивает администрация. Оформить подписку можно по кнопке «Подписка» вверху сайта.',
TRUE),
('AiTraderKa общается только со статуса «Наблюдатель»',
E'Мы изменили правила общения с ботом AiTraderKa. Теперь он отвечает на вопросы в чатах только участникам со статусом «Наблюдатель» и выше.\n\nКак получить статус: заходите на сайт каждый день, заполните профиль и добавьте монеты в портфель, чтобы набрать очки. Подписчики «Бронза», «Серебро» и «Золото» получают доступ к чатам сразу.\n\nМодерация чатов и форума от AiTraderKa работает как прежде: мат, реклама, ссылки и спам не пропускаются.',
TRUE);